import app from 'flarum/common/app';
function base() {
  return app.forum.attribute('apiUrl') + '/giveaways';
}
export function listGiveaways() {
  return app.request({
    method: 'GET',
    url: base()
  });
}
export function showGiveaway(idOrSlug) {
  return app.request({
    method: 'GET',
    url: `${base()}/${encodeURIComponent(idOrSlug)}`
  });
}
export function enterGiveaway(id) {
  return app.request({
    method: 'POST',
    url: `${base()}/${id}/enter`
  });
}
export function drawGiveaway(id) {
  return app.request({
    method: 'POST',
    url: `${base()}/${id}/draw`
  });
}

/** `answer` is the skill-testing answer, required only when the giveaway sets one. */
export function claimGiveaway(id, answer) {
  return app.request({
    method: 'POST',
    url: `${base()}/${id}/claim`,
    body: {
      data: {
        attributes: {
          answer: answer ?? ''
        }
      }
    }
  });
}
export function listEntrants(id, offset = 0) {
  return app.request({
    method: 'GET',
    url: `${base()}/${id}/entrants`,
    params: {
      page: {
        offset
      }
    }
  });
}
export function deleteGiveaway(id) {
  return app.request({
    method: 'DELETE',
    url: `${base()}/${id}`
  });
}
export function saveGiveaway(attributes, id) {
  return app.request({
    method: id ? 'PATCH' : 'POST',
    url: id ? `${base()}/${id}` : base(),
    body: {
      data: {
        attributes
      }
    }
  });
}
function catBase() {
  return app.forum.attribute('apiUrl') + '/giveaway-categories';
}
export function listCategories() {
  return app.request({
    method: 'GET',
    url: catBase()
  });
}
export function saveCategory(attributes, id) {
  return app.request({
    method: id ? 'PATCH' : 'POST',
    url: id ? `${catBase()}/${id}` : catBase(),
    body: {
      data: {
        attributes
      }
    }
  });
}
export function deleteCategory(id) {
  return app.request({
    method: 'DELETE',
    url: `${catBase()}/${id}`
  });
}
flarum.reg.add('ernestdefoe-giveaways', 'common/api', { listGiveaways: listGiveaways,showGiveaway: showGiveaway,enterGiveaway: enterGiveaway,drawGiveaway: drawGiveaway,claimGiveaway: claimGiveaway,listEntrants: listEntrants,deleteGiveaway: deleteGiveaway,saveGiveaway: saveGiveaway,listCategories: listCategories,saveCategory: saveCategory,deleteCategory: deleteCategory, });